const item = $input.first();
return [{
  json: {
    ...item.json,
    cfg: {
      testModus: true,
      ntfyFreigabe: false,
      ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
      ntfyTopic: 'instagram',
      graphUrl: 'https://graph.facebook.com/v23.0',
      igUserId: 'CHANGE-ME-IG-USER-ID',
      bildBasisUrl: 'https://instagram-bilder-prod.pke-lab.de/webhook/instagram-bild',
      bildVerzeichnis: '/data/instagram-bilder',
      sender: 'peter.kretzer@dlrg.org',
      betreff: 'INSTAGRAM',
      maxBilder: 10,
      minVerhaeltnis: 0.8,
      maxVerhaeltnis: 1.91,
      maxCaptionZeichen: 2200,
      maxHashtags: 30,
      maxErwaehnungen: 20
    }
  },
  binary: item.binary
}];

const item = $input.first();
const cfg = item.json.cfg;
const subject = String(item.json.subject || '').trim();
const from = typeof item.json.from === 'string' ? item.json.from : ((item.json.from && item.json.from.text) || '');
if (subject !== cfg.betreff) return [];
if (!from.toLowerCase().includes(cfg.sender.toLowerCase())) return [];
const binary = item.binary || {};
const keys = Object.keys(binary);
const isJson = (k) => binary[k].mimeType === 'application/json' || /\.json$/i.test(binary[k].fileName || '');
const isImage = (k) => /^image\//.test(binary[k].mimeType || '') || /\.(jpe?g|png|webp)$/i.test(binary[k].fileName || '');
const jsonKey = keys.find(isJson);
const imageKeys = keys.filter((k) => k !== jsonKey && isImage(k));
const ignored = keys.filter((k) => k !== jsonKey && !isImage(k)).map((k) => binary[k].fileName || k);
const base = { cfg, subject, from, imageKeys, ignored };
if (!jsonKey) return [{ json: { ...base, post: {}, mailError: 'Kein JSON-Anhang in der Mail' }, binary }];
const tryParse = (s) => {
  try { return JSON.parse(s); } catch (e) { return null; }
};
const jsonText = (await this.helpers.getBinaryDataBuffer(0, jsonKey)).toString('utf8').replace(/^﻿/, '').trim();
let post = tryParse(jsonText);
if (post === null && /^[A-Za-z0-9+/=\s]+$/.test(jsonText)) post = tryParse(Buffer.from(jsonText, 'base64').toString('utf8'));
if (!post || typeof post !== 'object' || Array.isArray(post)) {
  return [{ json: { ...base, post: {}, mailError: 'JSON-Anhang ist nicht lesbar' }, binary }];
}
return [{ json: { ...base, post }, binary }];

const item = $input.first();
const { cfg, post, mailError, imageKeys } = item.json;
const binary = item.binary || {};
const ignored = [...(item.json.ignored || [])];
const errors = [];
if (mailError) errors.push(mailError);

const pick = (...names) => {
  for (const name of names) {
    const v = post[name];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};
const toText = (v) => (typeof v === 'string' ? v.trim() : '');
const plain = (html) => html
  .replace(/<\s*br\s*\/?>/gi, '\n')
  .replace(/<\/\s*(p|div|h[1-6]|li|tr)\s*>/gi, '\n\n')
  .replace(/<[^>]*>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&amp;/g, '&')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const newToken = () => {
  const uuid = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID().replace(/-/g, '') : '';
  return uuid || Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
};

const tagsRaw = pick('hashtags', 'Hashtags');
const tagList = Array.isArray(tagsRaw) ? tagsRaw : (typeof tagsRaw === 'string' ? tagsRaw.split(/[\s,]+/) : []);
const hashtags = [...new Set(tagList.map((t) => String(t).trim().replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, '')).filter(Boolean))].map((t) => '#' + t);
const tagLine = hashtags.join(' ');

const titel = toText(pick('title', 'titel', 'Überschrift'));
const htmlRaw = toText(pick('html'));
const body = toText(pick('caption', 'Caption')) || [
  titel,
  toText(pick('subtitle', 'untertitel', 'Untertitel')),
  htmlRaw ? plain(htmlRaw) : toText(pick('text', 'Text'))
].filter(Boolean).join('\n\n');

const room = cfg.maxCaptionZeichen - (tagLine ? Array.from(tagLine).length + 2 : 0);
const bodyChars = Array.from(body);
const truncated = bodyChars.length > room;
const bodyFinal = truncated ? bodyChars.slice(0, Math.max(room - 1, 0)).join('').trimEnd() + '…' : body;
const caption = [bodyFinal, tagLine].filter(Boolean).join('\n\n');
if (!body) errors.push('Keine Caption (title, text oder caption fehlt im JSON)');
const tagCount = (caption.match(/#[\p{L}\p{N}_]+/gu) || []).length;
if (tagCount > cfg.maxHashtags) errors.push('Mehr als ' + cfg.maxHashtags + ' Hashtags (' + tagCount + ')');
const mentionCount = (caption.match(/@[\p{L}\p{N}_.]+/gu) || []).length;
if (mentionCount > cfg.maxErwaehnungen) errors.push('Mehr als ' + cfg.maxErwaehnungen + ' @-Erwähnungen (' + mentionCount + ')');
if (!cfg.testModus && /CHANGE-ME/.test(cfg.igUserId)) errors.push('igUserId im Node Konfiguration nicht gesetzt');

const exifOrientation = (buf, start, end) => {
  const le = buf.toString('latin1', start, start + 2) === 'II';
  const u16 = (o) => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  if (start + 8 > end) return 1;
  const ifd = start + u32(start + 4);
  if (ifd + 2 > end) return 1;
  const count = u16(ifd);
  for (let i = 0; i < count; i++) {
    const entry = ifd + 2 + i * 12;
    if (entry + 12 > end) break;
    if (u16(entry) === 0x0112) {
      const v = u16(entry + 8);
      return v >= 1 && v <= 8 ? v : 1;
    }
  }
  return 1;
};
const imageInfo = (buf) => {
  if (buf.length > 24 && buf.readUInt32BE(0) === 0x89504e47) {
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20), orientation: 1 };
  }
  if (buf.length > 4 && buf[0] === 0xff && buf[1] === 0xd8) {
    let o = 2;
    let orientation = 1;
    while (o + 4 <= buf.length) {
      if (buf[o] !== 0xff) { o++; continue; }
      const marker = buf[o + 1];
      if (marker === 0xff) { o++; continue; }
      if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) { o += 2; continue; }
      const len = buf.readUInt16BE(o + 2);
      if (marker === 0xe1 && buf.toString('latin1', o + 4, o + 10) === 'Exif\0\0') {
        orientation = exifOrientation(buf, o + 10, o + 2 + len);
      }
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        return { width: buf.readUInt16BE(o + 7), height: buf.readUInt16BE(o + 5), orientation };
      }
      o += 2 + len;
    }
    return null;
  }
  if (buf.length > 30 && buf.toString('latin1', 0, 4) === 'RIFF' && buf.toString('latin1', 8, 12) === 'WEBP') {
    const kind = buf.toString('latin1', 12, 16);
    if (kind === 'VP8 ') return { width: buf.readUInt16LE(26) & 0x3fff, height: buf.readUInt16LE(28) & 0x3fff, orientation: 1 };
    if (kind === 'VP8L') {
      const b = buf.subarray(21, 25);
      return { width: 1 + (b[0] | ((b[1] & 0x3f) << 8)), height: 1 + ((b[1] >> 6) | (b[2] << 2) | ((b[3] & 0x0f) << 10)), orientation: 1 };
    }
    if (kind === 'VP8X') {
      return { width: 1 + (buf[24] | (buf[25] << 8) | (buf[26] << 16)), height: 1 + (buf[27] | (buf[28] << 8) | (buf[29] << 16)), orientation: 1 };
    }
  }
  return null;
};

const usable = imageKeys.slice(0, cfg.maxBilder);
for (const k of imageKeys.slice(cfg.maxBilder)) ignored.push((binary[k].fileName || k) + ' (mehr als ' + cfg.maxBilder + ' Bilder)');
if (!imageKeys.length) errors.push('Keine Bilder in der Mail');

const lo = cfg.minVerhaeltnis + 0.005;
const hi = cfg.maxVerhaeltnis - 0.005;
const images = [];
for (const key of usable) {
  const meta = binary[key];
  const name = meta.fileName || key;
  const info = imageInfo(await this.helpers.getBinaryDataBuffer(0, key));
  if (!info || !info.width || !info.height) { errors.push('Bild ' + name + ': Format nicht lesbar (erlaubt: JPEG, PNG, WebP)'); continue; }
  const swapped = info.orientation >= 5;
  const dw = swapped ? info.height : info.width;
  const dh = swapped ? info.width : info.height;
  let cw = dw;
  let ch = dh;
  const ratio = dw / dh;
  if (ratio < cfg.minVerhaeltnis) ch = Math.floor(dw / lo);
  else if (ratio > cfg.maxVerhaeltnis) cw = Math.floor(dh * hi);
  images.push({
    fileName: name,
    binary: meta,
    breite: dw,
    hoehe: dh,
    zuschnitt: { breite: cw, hoehe: ch, x: Math.floor((dw - cw) / 2), y: Math.floor((dh - ch) / 2), zugeschnitten: cw !== dw || ch !== dh }
  });
}

if (errors.length) return [{ json: { valid: false, error: errors.join('; '), cfg, caption } }];

const token = newToken();
return images.map((img, index) => ({
  json: {
    valid: true,
    error: '',
    cfg,
    token,
    index,
    total: images.length,
    titel,
    caption,
    truncated,
    ignored,
    fileName: img.fileName,
    breite: img.breite,
    hoehe: img.hoehe,
    zuschnitt: img.zuschnitt
  },
  binary: { data: img.binary }
}));

const items = $input.all();
const erwartet = $('Beitrag pruefen').all().length;
const fehler = items.find((it) => it.json.error);
if (fehler || items.length !== erwartet) {
  return [{ json: { ok: false, schritt: 'Bildverarbeitung', antwort: { error: fehler ? fehler.json.error : 'Bild fehlt nach der Verarbeitung' } } }];
}
const first = $('Beitrag pruefen').first().json;
const urls = items.map((it, i) => first.cfg.bildBasisUrl + '?t=' + first.token + '&n=' + i);
return [{
  json: {
    ok: true,
    cfg: first.cfg,
    token: first.token,
    caption: first.caption,
    truncated: first.truncated,
    ignored: first.ignored,
    total: items.length,
    imageUrls: urls
  }
}];

const j = $input.first().json;
const code = j.statusCode;
const type = String((j.headers && j.headers['content-type']) || '');
if (code === 200 && type.startsWith('image/jpeg')) return [{ json: { ok: true } }];
const grund = code
  ? 'HTTP ' + code + (type ? ' (' + type + ')' : '')
  : (typeof j.error === 'string' ? j.error : JSON.stringify(j.error || j).slice(0, 300));
return [{ json: { ok: false, schritt: 'Bild-URL', antwort: { error: 'Bild unter ' + $('Beitrag buendeln').first().json.imageUrls[0] + ' nicht abrufbar: ' + grund } } }];

const b = $('Beitrag buendeln').first().json;
return b.imageUrls.map((url, i) => ({
  json: {
    imageUrl: url,
    index: i,
    total: b.imageUrls.length,
    caption: b.caption,
    apiBase: b.cfg.graphUrl + '/' + b.cfg.igUserId
  }
}));

const items = $input.all();
const ctx = $('Bilder aufteilen').first().json;
const ids = [];
let fehler = null;
items.forEach((it, i) => {
  if (it.json.id) ids.push(String(it.json.id));
  else if (!fehler) fehler = { bild: i + 1, antwort: it.json };
});
if (fehler || ids.length !== ctx.total) {
  return [{ json: { ok: false, schritt: 'Bild-Container' + (fehler ? ' (Bild ' + fehler.bild + ')' : ''), antwort: fehler ? fehler.antwort : {} } }];
}
return [{
  json: {
    ok: true,
    apiBase: ctx.apiBase,
    caption: ctx.caption,
    total: ctx.total,
    childIds: ids,
    creationId: ctx.total === 1 ? ids[0] : undefined
  }
}];

const j = $input.first().json;
const id = j.creationId || j.id;
if (!id) return [{ json: { ok: false, schritt: 'Karussell-Container', antwort: j } }];
return [{ json: { ok: true, creationId: String(id), apiBase: $('Container sammeln').first().json.apiBase } }];

const j = $input.first().json;
const ctx = $('Container-ID bestimmen').first().json;
const status = j.status_code;
if (status === 'FINISHED') return [{ json: { ...ctx, state: 'FINISHED' } }];
if (status === 'ERROR' || status === 'EXPIRED') {
  return [{ json: { ...ctx, state: 'FAIL', schritt: 'Container-Status', antwort: { error: status + (j.status ? ': ' + j.status : '') } } }];
}
if ($runIndex >= 36) {
  return [{ json: { ...ctx, state: 'FAIL', schritt: 'Container-Status', antwort: { error: 'Meta meldet nach 3 Minuten noch nicht FINISHED (' + (status || JSON.stringify(j.error || j).slice(0, 300)) + ')' } } }];
}
return [{ json: { ...ctx, state: 'WAIT' } }];

const j = $input.first().json;
if (!j.id) return [{ json: { ok: false, schritt: 'Veröffentlichen', antwort: j } }];
return [{ json: { ok: true, mediaId: String(j.id), apiBase: $('Container-ID bestimmen').first().json.apiBase } }];

const j = $input.first().json;
const fmt = (e) => {
  if (!e) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.error_user_title, e.error_user_msg, e.description];
  if (e.code) parts.push('Code ' + e.code);
  if (e.error_subcode) parts.push('Subcode ' + e.error_subcode);
  const text = parts.filter(Boolean).join(' | ');
  return text || JSON.stringify(e).slice(0, 500);
};
const schritt = j.schritt || 'Eingabe';
const grund = fmt(j.error) || fmt(j.antwort && j.antwort.error) || (j.antwort ? JSON.stringify(j.antwort).slice(0, 500) : 'unbekannt');
const caption = String($('Beitrag pruefen').first().json.caption || '');
const zeilen = ['Schritt: ' + schritt, 'Grund: ' + grund];
if (schritt === 'Veröffentlichen') zeilen.push('Unklar, ob der Post erschienen ist. Zuerst auf Instagram nachsehen, bevor die Mail erneut gesendet wird (sonst Dublette).');
if (caption) zeilen.push('', 'Post: ' + Array.from(caption.split('\n')[0]).slice(0, 80).join(''));
return [{ json: { text: zeilen.join('\n') } }];

const q = $input.first().json.query || {};
const t = String(q.t || '');
const n = String(q.n || '');
const ok = /^[0-9a-f]{32}$/.test(t) && /^[0-9]{1,2}$/.test(n);
return [{ json: { ok, datei: ok ? '/data/instagram-bilder/' + t + '-' + n + '.jpg' : '' } }];
